<script lang="ts">
  import {compileUiDocument,defaultSemanticElementCatalog,type UiDocument} from '@victframework/ui';
  import DocumentHost from '../../src/document/DocumentHost.svelte';
  import {aiAuthoringPackage} from '../../../ui-ai-svelte/src/authoring/knowledge.js';
  import {aiAuthoringDescriptors} from '../../../ui-ai-svelte/src/authoring/descriptors.js';
  import {aiAuthoringImplementations} from '../../../ui-ai-svelte/src/authoring/implementations.js';
  import '../../../ui-ai-svelte/dist/styles.css';
  import '../../src/rhea.css';
  function source(revision:string,themed=false,parts=false):UiDocument{
    const seed=aiAuthoringPackage.registrations.find(item=>item.descriptor.id==='vict.ai.conversation'&&item.descriptor.revision===revision)!.seed!;
    const nodes=Object.fromEntries(seed.nodes.map(node=>[node.id,node]));const conversation=nodes.conversation!,message=nodes.message!,prompt=nodes.prompt!;
    if(conversation.kind!=='component'||message.kind!=='component'||prompt.kind!=='component')throw Error('seed');
    return {schema:'vict.ui-document@1',id:`native-${revision}-${themed}-${parts}`,revision:'1',root:seed.root,nodes:{...nodes,
      conversation:{...conversation,slots:{...conversation.slots,messages:{name:'messages',children:['message','assistant']}}},
      message:{...message,props:{role:{type:'literal',value:'user'},text:{type:'literal',value:'User message'}},...(parts?{partStyles:{bubble:{localStyle:[{property:'background-color',value:{type:'text',value:'#00695c'}},{property:'color',value:{type:'text',value:'#ffffff'}},{property:'padding',value:{type:'text',value:'10px 12px'}}]}}}:{})},
      assistant:{...message,id:'assistant',props:{role:{type:'literal',value:'assistant'},text:{type:'literal',value:'Assistant reply'}},...(parts?{partStyles:{bubble:{localStyle:[{property:'background-color',value:{type:'text',value:'#e0f2f1'}},{property:'border-color',value:{type:'text',value:'#00695c'}},{property:'border-width',value:{type:'text',value:'2px'}},{property:'border-style',value:{type:'text',value:'solid'}},{property:'padding',value:{type:'text',value:'10px'}}]}}}:{})},
      prompt:{...prompt,...(parts?{partStyles:{field:{localStyle:[{property:'background-color',value:{type:'text',value:'#fffde7'}}]},send:{localStyle:[{property:'background-color',value:{type:'text',value:'#00695c'}},{property:'color',value:{type:'text',value:'#ffffff'}}]}}}:{})},
    },componentDefinitions:{},styleSources:{},tokens:{},conditions:{},assets:{},localState:{message:{key:'message',type:'string',initial:'Preview send'}},...(themed?{theme:{schema:'vict.ui-theme@1',roles:{surface:'#fff8e1',highlight:'#fbe9e7',highlightText:'#260e04',accent:'#00695c',accentText:'#fa1234',text:'#134e4a'}}}:{})};
  }
  const cases=[{id:'legacy',label:'Revision 1 default',source:source('1')},{id:'v2',label:'Revision 2 default',source:source('2')},{id:'legacy-custom',label:'Revision 1 custom AI aliases',source:source('1')},{id:'v2-custom',label:'Revision 2 custom AI aliases',source:source('2')},{id:'theme',label:'Revision 2 theme',source:source('2',true)},{id:'parts',label:'Revision 2 authored parts',source:source('2',true,true)}].map(item=>({...item,compiled:compileUiDocument(item.source,defaultSemanticElementCatalog(),aiAuthoringDescriptors)}));
  let measured=$state('Not measured. Use the button to read native computed styles.');
  function measure(){measured=JSON.stringify(cases.map(item=>{const root=document.querySelector(`[data-case="${item.id}"]`)!;const user=root.querySelector('[data-slot="bubble-content"]')!,assistant=root.querySelector('[data-ui-node="assistant"][data-ui-part="bubble"]'),field=root.querySelector('textarea')!,send=root.querySelector('button[aria-label="Send"]')!;return {case:item.id,userBackground:getComputedStyle(user).backgroundColor,userColor:getComputedStyle(user).color,assistantBubble:!!assistant,assistantBackground:assistant?getComputedStyle(assistant).backgroundColor:null,assistantBorder:assistant?getComputedStyle(assistant).borderTopWidth:null,fieldBackground:getComputedStyle(field).backgroundColor,sendBackground:getComputedStyle(send).backgroundColor,sendColor:getComputedStyle(send).color};}),null,2);}
</script>
<main class="hostile vict-rhea"><h1>Native AI part cascade verification</h1><p>Real built package CSS and canonical DocumentHost; no provider calls. Host button override is intentionally present.</p><button type="button" onclick={measure}>Measure painted targets</button><div class="cases">{#each cases as item}<section data-case={item.id} style={item.id.endsWith('custom') ? '--vict-ai-background:#fff3e0;--vict-ai-foreground:#5d4037;--vict-ai-primary:#e65100' : undefined}><h2>{item.label}</h2>{#if item.compiled.ok}<DocumentHost plan={item.compiled.plan} extensionDescriptors={aiAuthoringDescriptors} extensionImplementations={aiAuthoringImplementations} localState={item.source.localState} dispatch={async()=>{}} navigate={()=>{}}/>{:else}<pre>{JSON.stringify(item.compiled)}</pre>{/if}</section>{/each}</div><pre role="status">{measured}</pre></main>
<style>:global(body){margin:0;font-family:system-ui;background:#eef2f7}main{padding:20px}.cases{display:grid;grid-template-columns:repeat(4,minmax(240px,1fr));gap:16px}.cases>section{border:1px solid #cbd5e1;background:#fff;padding:10px;min-width:0}h1{font-size:22px}h2{font-size:15px}pre{white-space:pre-wrap;font-size:12px}:global(.hostile button){background-color:#ff00ff}</style>
